  await page.goto(file, { waitUntil: 'domcontentloaded' });
  const check = await page.textContent('#check');
  console.log(check);
  await page.screenshot({ path: 'web/usability/match-limit-original-points.png', fullPage: false });
  await browser.close();
  if (!check.includes('ok=true')) process.exit(1);
})().catch(e => { console.error(e); process.exit(1); });
